167: // Special non-enumerable properties to include when dumping objects (e.g., Error properties)
168: static const char *QTS_DUMP_SPECIAL_PROPS[] = {
169:   "name", "message", "stack", "fileName", "lineNumber"
170: };
171: #define QTS_DUMP_SPECIAL_PROPS_COUNT (sizeof(QTS_DUMP_SPECIAL_PROPS) / sizeof(QTS_DUMP_SPECIAL_PROPS[0]))
172: 
173: // Returns true if prop should be added to the clone:
174: // - Property exists (own or inherited) and has a non-undefined value
175: // - Property is NOT already an own enumerable property (which JSON.stringify would include)
176: static bool qts_should_copy_special_prop(JSContext *ctx, JSValueConst obj, const char *prop_name) {
177:   JSAtom prop_atom = JS_NewAtom(ctx, prop_name);
178: 
179:   // First check if property exists at all (including inherited)
180:   JSValue val = JS_GetProperty(ctx, obj, prop_atom);
181:   if (JS_IsException(val) || JS_IsUndefined(val)) {
182:     JS_FreeAtom(ctx, prop_atom);
183:     JS_FreeValue(ctx, val);
184:     return false;  // Property doesn't exist or is undefined
185:   }
186:   JS_FreeValue(ctx, val);
187: 
188:   // Property exists - check if it's an own enumerable property
189:   JSPropertyDescriptor desc;
190:   int ret = JS_GetOwnProperty(ctx, &desc, obj, prop_atom);
191:   JS_FreeAtom(ctx, prop_atom);
192: 
193:   if (ret != 1) {
194:     // Not an own property - but it exists (inherited), so we should copy it
195:     return true;
196:   }
197: 
198:   // It's an own property - check if enumerable
199:   bool is_enumerable = (desc.flags & JS_PROP_ENUMERABLE);
200: 
201:   // Free descriptor values
202:   JS_FreeValue(ctx, desc.value);
203:   if (desc.flags & JS_PROP_GETSET) {
204:     JS_FreeValue(ctx, desc.getter);
205:     JS_FreeValue(ctx, desc.setter);
206:   }
207: 
208:   // Copy if NOT enumerable (enumerable props are already included via JSON.stringify)
209:   return !is_enumerable;
210: }
211: 
212: // Creates clone with special props made enumerable, or JS_UNDEFINED if not needed
213: static JSValue qts_dump_create_clone(JSContext *ctx, JSValueConst obj) {
214:   if (!JS_IsObject(obj)) return JS_UNDEFINED;
215: 
216:   // Check if any special props need copying
217:   bool needs_clone = false;
218:   for (size_t i = 0; i < QTS_DUMP_SPECIAL_PROPS_COUNT; i++) {
219:     if (qts_should_copy_special_prop(ctx, obj, QTS_DUMP_SPECIAL_PROPS[i])) {
220:       needs_clone = true;
221:       break;
222:     }
223:   }
224:   if (!needs_clone) return JS_UNDEFINED;
225: 
226:   // Create clone with all enumerable props
227:   JSValue clone = JS_NewObject(ctx);
228:   if (JS_IsException(clone)) return clone;
229: 
230:   JSPropertyEnum *tab;
231:   uint32_t len;
232:   if (JS_GetOwnPropertyNames(ctx, &tab, &len, obj, JS_GPN_STRING_MASK | JS_GPN_ENUM_ONLY) < 0) {
233:     JS_FreeValue(ctx, clone);
234:     return JS_EXCEPTION;
235:   }
236: 
237:   for (uint32_t i = 0; i < len; i++) {
238:     JSValue val = JS_GetProperty(ctx, obj, tab[i].atom);
239:     if (!JS_IsException(val)) {
240:       JS_DefinePropertyValue(ctx, clone, tab[i].atom, val, JS_PROP_C_W_E);
241:     }
242:   }
243:   JS_FreePropertyEnum(ctx, tab, len);
244: 
245:   // Add special props (inherited or non-enumerable) as enumerable
246:   for (size_t i = 0; i < QTS_DUMP_SPECIAL_PROPS_COUNT; i++) {
247:     if (qts_should_copy_special_prop(ctx, obj, QTS_DUMP_SPECIAL_PROPS[i])) {
248:       JSAtom atom = JS_NewAtom(ctx, QTS_DUMP_SPECIAL_PROPS[i]);
249:       JSValue val = JS_GetProperty(ctx, obj, atom);
250:       if (!JS_IsException(val) && !JS_IsUndefined(val)) {
251:         JS_DefinePropertyValue(ctx, clone, atom, val, JS_PROP_C_W_E);
252:       } else {
253:         JS_FreeValue(ctx, val);
254:       }
255:       JS_FreeAtom(ctx, atom);
256:     }
257:   }
258: 
259:   return clone;
260: }
