272: static void qts_debugbuf_write(void *opaque, const char *data, size_t len) {
273:   qts_debugbuf *s = opaque;
274:   size_t remaining = s->size - s->pos - 1; // -1 for null terminator
275:   if (len > remaining) len = remaining;
276:   if (len > 0) {
277:     memcpy(s->buf + s->pos, data, len);
278:     s->pos += len;
279:     s->buf[s->pos] = '\0';
280:   }
281: }
