284: // Returns a fallback string when JSON serialization fails
285: static JSBorrowedChar *qts_dump_get_fallback(JSContext *ctx, JSValueConst obj, JSValue exception) {
286:   char buf[QTS_DUMP_FALLBACK_SIZE];
287:   size_t pos = 0;
288:   buf[0] = '\0';
289: 
290: #ifndef QTS_USE_QUICKJS_NG
291:   // bellard/quickjs: Use JS_PrintValue with show_hidden for rich debug output
292:   qts_debugbuf dbuf = { buf, sizeof(buf), 0 };
293: 
294:   JSPrintValueOptions options;
295:   JS_PrintValueSetDefaultOptions(&options);
296:   options.show_hidden = true;
297:   options.max_depth = 3;
298:   options.max_string_length = 200;
299:   options.max_item_count = 20;
300: 
301:   JS_PrintValue(ctx, qts_debugbuf_write, &dbuf, obj, &options);
302:   pos = dbuf.pos;
303: #else
304:   // quickjs-ng: JS_PrintValue not available, use toString() instead
305:   JSValue to_string_val = JS_ToString(ctx, obj);
306:   if (JS_IsException(to_string_val)) {
307:     JS_FreeValue(ctx, JS_GetException(ctx));
308:     pos = snprintf(buf, sizeof(buf), "(toString failed)");
309:   } else {
310:     const char *str = JS_ToCString(ctx, to_string_val);
311:     if (str) {
312:       size_t len = strlen(str);
313:       if (len > sizeof(buf) - 100) len = sizeof(buf) - 100; // Reserve space for error info
314:       memcpy(buf, str, len);
315:       buf[len] = '\0';
316:       pos = len;
317:       JS_FreeCString(ctx, str);
318:     }
319:     JS_FreeValue(ctx, to_string_val);
320:   }
321: #endif
322: 
323:   // Add separator and error info
324:   const char *err_msg = NULL;
325:   if (!JS_IsUndefined(exception) && !JS_IsNull(exception)) {
326:     JSValue msg = JS_GetPropertyStr(ctx, exception, "message");
327:     if (!JS_IsException(msg) && JS_IsString(msg)) {
328:       err_msg = JS_ToCString(ctx, msg);
329:     }
330:     JS_FreeValue(ctx, msg);
331:   }
332: 
333:   size_t remaining = sizeof(buf) - pos - 1;
334:   snprintf(buf + pos, remaining, "\n---\nnot JSON serializable: %s",
335:            err_msg ? err_msg : "(unknown error)");
336: 
337:   if (err_msg) JS_FreeCString(ctx, err_msg);
338: 
339:   JSValue result_str = JS_NewString(ctx, buf);
340:   JSBorrowedChar *result = QTS_GetString(ctx, &result_str);
341:   JS_FreeValue(ctx, result_str);
342:   return result;
343: }
