486: // ----------------------------------------------------------------------------
487: // HostRef - De-reference host value based on JSValue GC.
488: // Used for functions
489: 
490: static JSClassID host_ref_class_id;
491: // todo: variant with mark callback
492: 
493: typedef struct HostRef {
494:   int32_t id;
495: } HostRef;
496: 
497: #ifdef __EMSCRIPTEN__
498: EM_JS(void, qts_host_ref_free, (JSRuntime *rt, int32_t id), {
499:   // For now we don't allow for async freeHostRef.
500:   const asyncify = undefined;
501:   Module['callbacks']['freeHostRef'](asyncify, rt, id);
502: });
503: #endif
504: 
505: static void host_ref_finalizer(JSRuntime *rt, JSValue val) {
506:   HostRef *hv = JS_GetOpaque(val, host_ref_class_id);
507:   if (hv) {
508: #ifdef __EMSCRIPTEN__
509:     qts_host_ref_free(rt, hv->id);
510: #endif
511:     js_free_rt(rt, hv);
512:   }
513: }
514: 
515: static JSClassDef host_ref_class = {
516:   .class_name = "HostRef",
517:   .finalizer = host_ref_finalizer,
518: };
519: 
520: static int host_ref_class_init(JSRuntime *rt) {
521:   // Only allocate class ID once globally
522:   if (host_ref_class_id == 0) {
523: #ifdef QTS_USE_QUICKJS_NG
524:     JS_NewClassID(rt, &host_ref_class_id);
525: #else
526:     JS_NewClassID(&host_ref_class_id);
527: #endif
528:   }
529:   // Register class with this runtime if not already registered
530:   // JS_NewClass returns 0 on success, -1 if already registered (which is fine)
531:   if (!JS_IsRegisteredClass(rt, host_ref_class_id)) {
532:     return JS_NewClass(rt, host_ref_class_id, &host_ref_class);
533:   }
534:   return 0;
535: }
536: 
537: static JSValue new_host_ref(JSContext *ctx, HostRefId id) {
538:   HostRef *hv;
539:   JSValue obj;
540:   obj = JS_NewObjectClass(ctx, host_ref_class_id);
541:   if (JS_IsException(obj)) {
542:     return obj;
543:   }
544: 
545:   hv = js_mallocz(ctx, sizeof(*hv));
546:   if (!hv) {
547:     // js_mallocz returns NULL on failure and sets rt.exception to OutOfMemory
548:     JS_FreeValue(ctx, obj);
549:     return JS_EXCEPTION;
550:   }
551: 
