603: JSContext *QTS_NewContext(JSRuntime *rt, IntrinsicsFlags intrinsics) {
604:   JSContext *ctx;
605: 
606:   if (intrinsics == 0) {
607:     ctx = JS_NewContext(rt);
608:     if (ctx == NULL) {
609:       return NULL;
610:     }
611:   } else {
612:     ctx = JS_NewContextRaw(rt);
613:     if (ctx == NULL) {
614:       return NULL;
615:     }
616: 
617:     if (intrinsics & QTS_Intrinsic_BaseObjects) {
618:       JS_AddIntrinsicBaseObjects(ctx);
619:     }
620:     if (intrinsics & QTS_Intrinsic_Date) {
621:       JS_AddIntrinsicDate(ctx);
622:     }
623:     if (intrinsics & QTS_Intrinsic_Eval) {
624:       JS_AddIntrinsicEval(ctx);
625:     }
626:   #ifndef QTS_USE_QUICKJS_NG
627:     if (intrinsics & QTS_Intrinsic_StringNormalize) {
628:       JS_AddIntrinsicStringNormalize(ctx);
629:     }
630:   #endif
631:     if (intrinsics & QTS_Intrinsic_RegExp) {
632:       JS_AddIntrinsicRegExp(ctx);
633:     }
634:     if (intrinsics & QTS_Intrinsic_RegExpCompiler) {
635:       JS_AddIntrinsicRegExpCompiler(ctx);
636:     }
637:     if (intrinsics & QTS_Intrinsic_JSON) {
638:       JS_AddIntrinsicJSON(ctx);
639:     }
640:     if (intrinsics & QTS_Intrinsic_Proxy) {
641:       JS_AddIntrinsicProxy(ctx);
642:     }
643:     if (intrinsics & QTS_Intrinsic_MapSet) {
644:       JS_AddIntrinsicMapSet(ctx);
645:     }
646:     if (intrinsics & QTS_Intrinsic_TypedArrays) {
647:       JS_AddIntrinsicTypedArrays(ctx);
648:     }
649:     if (intrinsics & QTS_Intrinsic_Promise) {
650:       JS_AddIntrinsicPromise(ctx);
651:     }
652: 
653:     // Note: BigInt is now always part of QuickJS core, no need for separate intrinsic
654:   }
655: 
656:   if (host_ref_class_init(JS_GetRuntime(ctx)) != 0) {
657:     JS_FreeContext(ctx);
658:     return NULL;
659:   }
660: 
661:   return ctx;
662: }
