746: JSValue qts_get_symbol_key(JSContext *ctx, JSValueConst *value) {
747:   JSValue global = JS_GetGlobalObject(ctx);
748:   JSValue Symbol = JS_GetPropertyStr(ctx, global, "Symbol");
749:   JS_FreeValue(ctx, global);
750: 
751:   JSValue Symbol_keyFor = JS_GetPropertyStr(ctx, Symbol, "keyFor");
752:   JSValue key = JS_Call(ctx, Symbol_keyFor, Symbol, 1, value);
753:   JS_FreeValue(ctx, Symbol_keyFor);
754:   JS_FreeValue(ctx, Symbol);
755:   return key;
756: }
