758: JSValue *QTS_NewSymbol(JSContext *ctx, BorrowedHeapChar *description, int isGlobal) {
759:   JSValue global = JS_GetGlobalObject(ctx);
760:   JSValue Symbol = JS_GetPropertyStr(ctx, global, "Symbol");
761:   JS_FreeValue(ctx, global);
762:   JSValue descriptionValue = JS_NewString(ctx, description);
763:   JSValue symbol;
764: 
765:   if (isGlobal != 0) {
766:     JSValue Symbol_for = JS_GetPropertyStr(ctx, Symbol, "for");
767:     symbol = JS_Call(ctx, Symbol_for, Symbol, 1, &descriptionValue);
768:     JS_FreeValue(ctx, descriptionValue);
769:     JS_FreeValue(ctx, Symbol_for);
770:     JS_FreeValue(ctx, Symbol);
771:     return jsvalue_to_heap(symbol);
772:   }
773: 
774:   symbol = JS_Call(ctx, Symbol, JS_UNDEFINED, 1, &descriptionValue);
775:   JS_FreeValue(ctx, descriptionValue);
776:   JS_FreeValue(ctx, Symbol);
777: 
778:   return jsvalue_to_heap(symbol);
779: }
