813: /*
814:   runs pending jobs (Promises/async functions) until it encounters
815:   an exception or it executed the passed maxJobsToExecute jobs.
816: 
817:   Passing a negative value will run the loop until there are no more
818:   pending jobs or an exception happened
819: 
820:   Returns the executed number of jobs or the exception encountered
821: */
822: MaybeAsync(JSValue *) QTS_ExecutePendingJob(JSRuntime *rt, int maxJobsToExecute, JSContext **lastJobContext) {
823:   JSContext *pctx;
824:   int status = 1;
825:   int executed = 0;
826:   while (executed != maxJobsToExecute && status == 1) {
827:     status = JS_ExecutePendingJob(rt, &pctx);
828:     if (status == -1) {
829:       *lastJobContext = pctx;
830:       return jsvalue_to_heap(JS_GetException(pctx));
831:     } else if (status == 1) {
832:       *lastJobContext = pctx;
833:       executed++;
834:     }
835:   }
836:   IF_DEBUG_RT {
837:     char msg[LOG_LEN];
838:     snprintf(msg, LOG_LEN, "QTS_ExecutePendingJob(executed: %d, pctx: %p, lastJobExecuted: %p)", executed, pctx, *lastJobContext);
839:     qts_log(msg);
840:   }
841:   return jsvalue_to_heap(JS_NewFloat64(pctx, executed));
842: }
