864: void QTS_DefineProp(JSContext *ctx, JSValueConst *this_val, JSValueConst *prop_name, JSValueConst *prop_value, JSValueConst *get, JSValueConst *set, bool configurable, bool enumerable, bool has_value) {
865:   JSAtom prop_atom = JS_ValueToAtom(ctx, *prop_name);
866: 
867:   int flags = 0;
868:   if (configurable) {
869:     flags = flags | JS_PROP_CONFIGURABLE;
870:     if (has_value) {
871:       flags = flags | JS_PROP_HAS_CONFIGURABLE;
872:     }
873:   }
874:   if (enumerable) {
875:     flags = flags | JS_PROP_ENUMERABLE;
876:     if (has_value) {
877:       flags = flags | JS_PROP_HAS_ENUMERABLE;
878:     }
879:   }
880:   if (!JS_IsUndefined(*get)) {
881:     flags = flags | JS_PROP_HAS_GET;
882:   }
883:   if (!JS_IsUndefined(*set)) {
884:     flags = flags | JS_PROP_HAS_SET;
885:   }
886:   if (has_value) {
887:     flags = flags | JS_PROP_HAS_VALUE;
888:   }
889: 
890:   JS_DefineProperty(ctx, *this_val, prop_atom, *prop_value, *get, *set, flags);
891:   JS_FreeAtom(ctx, prop_atom);
892: }
