894: #define JS_ATOM_TAG_INT (1U << 31)
895: static inline BOOL __JS_AtomIsTaggedInt(JSAtom v) {
896:   return (v & JS_ATOM_TAG_INT) != 0;
897: }
898: 
899: static inline uint32_t __JS_AtomToUInt32(JSAtom atom) {
900:   return atom & ~JS_ATOM_TAG_INT;
901: }
902: 
903: /* include numbers. when only this is set, we filter out strings */
904: #define QTS_GPN_NUMBER_MASK (1 << 6)
905: /* Treat numbers as strings */
906: #define QTS_STANDARD_COMPLIANT_NUMBER (1 << 7)
907: 
908: MaybeAsync(JSValue *) QTS_GetOwnPropertyNames(JSContext *ctx, JSValue ***out_ptrs, uint32_t *out_len, JSValueConst *obj, int flags) {
909:   JSPropertyEnum *tab = NULL;
910:   uint32_t total_props = 0;
911:   uint32_t out_props = 0;
912: 
913:   BOOL qts_standard_compliant_number = (flags & QTS_STANDARD_COMPLIANT_NUMBER) != 0;
914:   BOOL qts_include_string = (flags & JS_GPN_STRING_MASK) != 0;
915:   BOOL qts_include_number = qts_standard_compliant_number ? 0 : (flags & QTS_GPN_NUMBER_MASK) != 0;
916:   if (qts_include_number) {
917:     // if we want numbers, we must include strings in call down
918:     flags = flags | JS_GPN_STRING_MASK;
919:   }
920: 
921:   int status = 0;
922:   status = JS_GetOwnPropertyNames(ctx, &tab, &total_props, *obj, flags);
923:   if (status < 0) {
924:     if (tab != NULL) {
925:       js_free(ctx, tab);
926:     }
927:     return jsvalue_to_heap(JS_GetException(ctx));
928:   }
929:   *out_ptrs = malloc(sizeof(JSValue) * total_props);
930:   for (int i = 0; i < total_props; i++) {
931:     JSAtom atom = tab[i].atom;
932: 
933:     if (__JS_AtomIsTaggedInt(atom)) {
934:       if (qts_include_number) {
935:         uint32_t v = __JS_AtomToUInt32(atom);
936:         (*out_ptrs)[out_props++] = jsvalue_to_heap(JS_NewUint32(ctx, v));
937:       } else if (qts_include_string && qts_standard_compliant_number) {
938:         (*out_ptrs)[out_props++] = jsvalue_to_heap(JS_AtomToValue(ctx, tab[i].atom));
939:       }
940:       JS_FreeAtom(ctx, atom);
941:       continue;
942:     }
943: 
944:     JSValue atom_value = JS_AtomToValue(ctx, atom);
945:     JS_FreeAtom(ctx, atom);
946: 
947:     if (JS_IsString(atom_value)) {
948:       if (qts_include_string) {
949:         (*out_ptrs)[out_props++] = jsvalue_to_heap(atom_value);
950:       } else {
951:         JS_FreeValue(ctx, atom_value);
952:       }
953:     } else {  // Symbol
954:       // We must have set the includeSymbol or includePrivate flags
955:       // if it's present
956:       (*out_ptrs)[out_props++] = jsvalue_to_heap(atom_value);
957:     }
958:   }
959:   js_free(ctx, tab);
960:   *out_len = out_props;
961:   return NULL;
962: }
