1021: // QTS_DetectModule - bellard/quickjs style module detection heuristic.
1022: // For quickjs-ng, this is patched into the amalgam (see vendor/quickjs-ng-patches/).
1023: // It uses bellard's approach: skip whitespace/comments, check for 'import' or 'export'.
1024: #ifdef QTS_USE_QUICKJS_NG
1025: extern bool QTS_DetectModule(const char *input, size_t input_len);
1026: #endif
1027: 
1028: MaybeAsync(JSValue *) QTS_Eval(JSContext *ctx, BorrowedHeapChar *js_code, size_t js_code_length, const char *filename, EvalDetectModule detectModule, EvalFlags evalFlags) {
1029:   char msg[LOG_LEN];
1030: #ifdef QTS_USE_QUICKJS_NG
1031:   // quickjs-ng's JS_DetectModule has different behavior - it parses the code
1032:   // as a module and returns true if parsing succeeds. Since any valid JS
1033:   // expression is valid module syntax, this incorrectly detects non-modules.
1034:   // Use bellard/quickjs heuristic: check for import/export keywords at start.
1035:   if (detectModule) {
1036:     if (QTS_DetectModule((const char *)js_code, js_code_length)) {
1037:       QTS_DEBUG("QTS_Eval: quickjs-ng heuristic detected module = true");
1038:       evalFlags |= JS_EVAL_TYPE_MODULE;
1039:     } else {
1040:       QTS_DEBUG("QTS_Eval: quickjs-ng heuristic detected module = false");
1041:     }
1042:   } else {
1043:     QTS_DEBUG("QTS_Eval: do not detect module");
1044:   }
1045: #else
1046:   if (detectModule) {
1047:     if (JS_DetectModule((const char *)js_code, js_code_length)) {
1048:       QTS_DEBUG("QTS_Eval: Detected module = true");
1049:       evalFlags |= JS_EVAL_TYPE_MODULE;
1050:     } else {
1051:       QTS_DEBUG("QTS_Eval: Detected module = false");
1052:     }
1053:   } else {
1054:     QTS_DEBUG("QTS_Eval: do not detect module");
1055:   }
1056: #endif
1057: 
1058:   JSModuleDef *module;
1059:   JSValue eval_result;
1060:   if (
1061:       (evalFlags & JS_EVAL_TYPE_MODULE) != 0 &&
1062:       (evalFlags & JS_EVAL_FLAG_COMPILE_ONLY) == 0) {
1063:     QTS_DEBUG("QTS_Eval: JS_EVAL_TYPE_MODULE");
1064:     JSValue func_obj = JS_Eval(ctx, js_code, js_code_length, filename, evalFlags | JS_EVAL_FLAG_COMPILE_ONLY);
1065:     if (JS_IsException(func_obj)) {
1066:       QTS_DEBUG("QTS_Eval: JS_EVAL_FLAG_COMPILE_ONLY exception")
1067:       return jsvalue_to_heap(func_obj);
1068:     }
1069: 
1070:     if (JS_VALUE_GET_TAG(func_obj) != JS_TAG_MODULE) {
1071:       QTS_DEBUG("QTS_Eval: JS_EVAL_FLAG_COMPILE_ONLY result != JS_TAG_MODULE")
1072:       JS_FreeValue(ctx, func_obj);
1073:       return jsvalue_to_heap(JS_ThrowInternalError(ctx, "Module code compiled to non-module object"));
1074:     }
1075: 
1076:     module = JS_VALUE_GET_PTR(func_obj);
1077:     if (module == NULL) {
1078:       QTS_DEBUG("QTS_Eval: JSModuleDef == NULL")
1079:       JS_FreeValue(ctx, func_obj);
1080:       return jsvalue_to_heap(JS_ThrowInternalError(ctx, "Module compiled to null"));
1081:     }
1082: 
1083:     eval_result = JS_EvalFunction(ctx, func_obj);
1084:     QTS_DEBUG("QTS_Eval: JS_EVAL_TYPE_MODULE eval_result")
1085:     // It seems like this is a double-free.
1086:     // JS_FreeValue(ctx, func_obj);
1087:   } else {
1088:     eval_result = JS_Eval(ctx, js_code, js_code_length, filename, evalFlags);
1089:     QTS_DEBUG("QTS_Eval: JS_EVAL_TYPE_GLOBAL eval_result")
1090:   }
1091: 
1092:   IF_DEBUG {
1093:     snprintf(msg, LOG_LEN, "QTS_Eval: eval_result = %d", JS_VALUE_GET_TAG(eval_result));
1094:     qts_log(msg);
1095:   }
1096: 
1097:   if (
1098:       // Error - nothing more to do.
1099:       JS_IsException(eval_result)
1100:       // Non-module eval - return the result
1101:       || (evalFlags & JS_EVAL_TYPE_MODULE) == 0) {
1102:     QTS_DEBUG("QTS_Eval: non-module or exception")
1103:     return jsvalue_to_heap(eval_result);
1104:   }
1105: 
1106:   // We eval'd a module.
1107:   // Make our return type `ModuleExports | Promise<ModuleExports>>`
1108:   JSPromiseStateEnum state = JS_PromiseState(ctx, eval_result);
1109:   IF_DEBUG {
1110:     snprintf(msg, LOG_LEN, "QTS_Eval: eval_result JS_PromiseState = %i", state);
1111:     qts_log(msg);
1112:   }
1113:   if (
1114:       // quickjs@2024-01-14 evaluating module
1115:       // produced a promise
1116:       (state == JS_PROMISE_FULFILLED)
1117:       // quickjs in compile mode
1118:       // quickjs-ng before rebasing on quickjs@2024-01-14
1119:       // not a promise.
1120:       || (state == -1)) {
1121:     QTS_DEBUG("QTS_Eval: result: JS_PROMISE_FULFILLED or not a promise")
1122:     JS_FreeValue(ctx, eval_result);
1123:     return jsvalue_to_heap(JS_GetModuleNamespace(ctx, module));
1124:   } else if (state == JS_PROMISE_REJECTED) {
1125:     // Throw the rejection response, to match evaluation of non-module code,
1126:     // or of code with a syntax error.
1127:     QTS_DEBUG("QTS_Eval: result: JS_PROMISE_REJECTED - throw rejection reason")
1128:     JS_Throw(ctx, JS_PromiseResult(ctx, eval_result));
1129:     JS_FreeValue(ctx, eval_result);
1130:     return jsvalue_to_heap(JS_EXCEPTION);
1131:   } else if (state == JS_PROMISE_PENDING) {
1132:     QTS_DEBUG("QTS_Eval: result: JS_PROMISE_PENDING")
1133:     // return moduleDone.then(() => module_namespace)
1134:     JSValue module_namespace = JS_GetModuleNamespace(ctx, module);
1135:     if (JS_IsException(module_namespace)) {
1136:       QTS_DEBUG("QTS_Eval: module_namespace exception")
1137:       JS_FreeValue(ctx, eval_result);
1138:       return jsvalue_to_heap(module_namespace);
1139:     }
1140: 
1141:     JSValue then_resolve_module_namespace = JS_NewCFunctionData(ctx, &qts_resolve_func_data, 0, 0, 1, &module_namespace);
1142:     JS_FreeValue(ctx, module_namespace);
1143:     if (JS_IsException(then_resolve_module_namespace)) {
1144:       QTS_DEBUG("QTS_Eval: then_resolve_module_namespace exception")
1145:       JS_FreeValue(ctx, eval_result);
1146:       return jsvalue_to_heap(then_resolve_module_namespace);
1147:     }
1148: 
1149:     JSAtom then_atom = JS_NewAtom(ctx, "then");
1150:     JSValue new_promise = JS_Invoke(ctx, eval_result, then_atom, 1, &then_resolve_module_namespace);
1151:     QTS_DEBUG("QTS_Eval: new_promise = promise.then(() => resolveModuleNamespace())")
1152:     JS_FreeAtom(ctx, then_atom);
1153:     JS_FreeValue(ctx, then_resolve_module_namespace);
1154:     JS_FreeValue(ctx, eval_result);
1155: 
1156:     return jsvalue_to_heap(new_promise);
1157:   } else {
1158:     // Unknown case
1159:     QTS_DEBUG("QTS_Eval: unknown JSPromiseStateEnum")
1160:     return jsvalue_to_heap(eval_result);
1161:   }
1162: }
