1459:   JSValue func_val = JS_Eval(ctx, module_body, strlen(module_body), module_name, JS_EVAL_TYPE_MODULE | JS_EVAL_FLAG_COMPILE_ONLY);
1460:   if (JS_IsException(func_val)) {
1461:     return NULL;
1462:   }
1463:   // TODO: Is exception ok?
1464:   // TODO: set import.meta?
1465:   JSModuleDef *module = JS_VALUE_GET_PTR(func_val);
1466:   JS_FreeValue(ctx, func_val);
1467:   return module;
